#!/usr/bin/env python3
"""Convert lm_eval --log_samples output to IRT-compatible format.

lm_eval saves per-sample JSONL files under:
  <output_path>/<model_name>/samples_<task>_<timestamp>.jsonl

This script finds all samples_*.jsonl, extracts per-item correctness,
and writes eval_results.json, correctness_matrix.json, item_responses.json
matching the format expected by downstream IRT analysis.
"""
import argparse
import json
from pathlib import Path


BENCHMARK_MAP = {
    "arc_challenge": "arc_challenge",
}


def normalize_benchmark(task_name):
    """Map lm_eval task name to our benchmark name."""
    if task_name in BENCHMARK_MAP:
        return BENCHMARK_MAP[task_name]
    if task_name.startswith("mmlu_"):
        return "mmlu"
    return task_name


def extract_correct(sample, task_name):
    """Extract correctness from a lm_eval sample dict."""
    if "acc" in sample:
        return bool(sample["acc"])
    if "exact_match" in sample:
        return bool(sample["exact_match"])
    if "filtered_resps" in sample and "target" in sample:
        pred = sample["filtered_resps"][0] if sample["filtered_resps"] else ""
        return str(pred).strip() == str(sample["target"]).strip()
    return False


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--input-dir", required=True, help="lm_eval output root dir")
    parser.add_argument("--output-dir", required=True, help="IRT output dir")
    args = parser.parse_args()

    input_dir = Path(args.input_dir)
    output_dir = Path(args.output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    sample_files = sorted(input_dir.rglob("samples_*.jsonl"))
    if not sample_files:
        print(f"WARNING: No samples_*.jsonl found under {input_dir}")
        return

    benchmarks = {}
    item_responses = []

    for sf in sample_files:
        fname = sf.stem
        parts = fname.split("_")
        task_name = "_".join(parts[1:-1]) if len(parts) > 2 else parts[1]
        bench_key = normalize_benchmark(task_name)

        if bench_key not in benchmarks:
            benchmarks[bench_key] = {"per_item": [], "correct": 0, "total": 0}

        with open(sf) as f:
            for line in f:
                if not line.strip():
                    continue
                sample = json.loads(line)
                is_correct = extract_correct(sample, task_name)
                doc_id = sample.get("doc_id", benchmarks[bench_key]["total"])

                item_id = f"{task_name}_{doc_id}"
                pred = ""
                if "filtered_resps" in sample:
                    pred = str(sample["filtered_resps"][0]) if sample["filtered_resps"] else ""
                gold = str(sample.get("target", ""))

                benchmarks[bench_key]["per_item"].append({
                    "index": doc_id,
                    "correct": is_correct,
                    "pred": pred,
                    "gold": gold,
                    "subtask": task_name,
                    "item_id": item_id,
                })
                benchmarks[bench_key]["total"] += 1
                if is_correct:
                    benchmarks[bench_key]["correct"] += 1

                item_responses.append({
                    "item_id": item_id,
                    "benchmark": bench_key,
                    "correct": is_correct,
                    "model_answer": pred,
                    "gold_answer": gold,
                })

    all_results = {"benchmarks": {}}
    correctness_matrix = {}

    for bench_key, data in benchmarks.items():
        total = data["total"]
        correct = data["correct"]
        all_results["benchmarks"][bench_key] = {
            "accuracy": correct / total if total > 0 else 0,
            "correct": correct,
            "total": total,
            "per_item": data["per_item"],
        }
        correctness_matrix[bench_key] = [item["correct"] for item in data["per_item"]]
        print(f"{bench_key}: {correct}/{total} = {correct/total:.4f}" if total > 0 else f"{bench_key}: no items")

    with open(output_dir / "eval_results.json", "w") as f:
        json.dump(all_results, f, indent=2, ensure_ascii=False)
    with open(output_dir / "correctness_matrix.json", "w") as f:
        json.dump(correctness_matrix, f)
    with open(output_dir / "item_responses.json", "w") as f:
        json.dump(item_responses, f, indent=2, ensure_ascii=False)

    (output_dir / ".done").touch()
    print(f"IRT files saved to {output_dir}")


if __name__ == "__main__":
    main()
